use vstd::prelude::*;

verus! {
    // Reverse a vector of f32’s.
    // Ensures the result has the same length as the input,
    // and for all valid indices i, result[i] == m[n-1-i].
    fn numpy_flip(m: Vec<f32>) -> (result: Vec<f32>)
        ensures
            result.len() == m.len(),
            forall |i: usize| i < result.len() ==>
                result[i] == m[m.len() - 1 - i],
    {
        let n = m.len();
        let mut res: Vec<f32> = Vec::new();
        let mut i: usize = n;
        // We build res by repeatedly popping from the end of m “conceptually”,
        // i.e. by pushing m[i-1] for i = n, n-1, …, 1.
        while i > 0
            invariant
                // i always stays between 0 and n
                i <= n,
                // we have pushed exactly (n - i) elements so far
                res.len() == n - i,
                // for each k < res.len(), res[k] = m[n-1-k]
                forall |k: usize| k < res.len() ==>
                    res[k] == m[n - 1 - k],
            decreases i,
        {
            i = i - 1;
            // f32 is Copy, so indexing returns an f32 value
            let x: f32 = m[i];
            res.push(x);
        }
        res
    }
}

